SELECT /* SQL-ID : isry.couns.taskwksprt.taskwkandatdmng.mapper.TaskwkReprtsMapper.selectChkListQuestList : 체크리스트질의 목록 조회 */ ROWNUM AS ROW_NUM /* 행번호 */ , CHKLST_QUEST_SN /* 체크리스트질의일련번호 */ , CHKLST_GROUP_SN /* 체크리스트그룹일련번호 */ , QUEST_NO /* 질의번호 */ , CHKLST_SCORE /* 체크리스트점수 */ , CHKLST_CN /* 체크리스트내용 */ FROM AYC260 /* 체크리스트질의 */ WHERE 1=1
AND CHKLST_QUEST_SN IN
#{item}

    /* SQL-ID : isry.couns.taskwksprt.taskwkandatdmng.mapper.TaskwkReprtsMapper.selectCnsltntCommuteInfo : 상담원출퇴근관리(AYC495) 업무보고서 등록 근무일자에 대한 데이터 확인 */
	    SELECT  COUNT(*)
		FROM    AYC495
		WHERE   1=1
		AND     CONSTT_ID   =   #{CNSLTNT_ID}
		AND     WORK_YMD    =   REPLACE(#{WORK_YMD}, '-', '')

