PSTG_NOCS /* JAM게시건수 */ , JAM_CRISIS_CN /* JAM위기내용 */ , MSNGR_NOCS /* 메신저건수(아웃리치) */ , MSNGR_CRCO_CN /* 메신저위기상담내용 (아웃리치) */ , CMNT_DSCSN_NOCS /* 댓글상담건수 (아웃리치) */ , CMNT_DSCSN_CRCO_CN /* 댓글상담위기상담내용 (아웃리치) */ , PR_NOCS /* 홍보건수 (아웃리치) */ , PR_CRCO_CN /* 홍보위기상담내용 (아웃리치) */ , OUTRC_CHLNG_PRFMNC_NOCS /* 아웃리치챌린지실적건수 : AS-IS 사용안함? */ , FRST_RGTR_ID /* 최초등록자아이디 */ , FRST_REG_DT /* 최초등록일시 */ , LAST_MDFR_ID /* 최종수정자아이디 */ , LAST_MDFCN_DT /* 최종수정일시 */ ) VALUES ( #{TASKWK_REPRTS_INDEX_SN} /* 업무보고서색인일련번호 */ , #{CNSLTNT_ID} /* 상담사아이디 */ , TO_DATE(#{CHTT_ATENDB_DT}, 'YYYY-MM-DD HH24:MI:SS') /* 채팅출근일시 */ , NVL(#{NTABRD_RLS_NOCS}, 0) /* 게시판공개건수 */ , NVL(#{NTABRD_CLSDR_NOCS}, 0) /* 게시판비공개건수 */ , NVL(#{NTABRD_DAUM_NOCS}, 0) /* 게시판DAUM건수 */ , NVL(#{NTABRD_NAVER_NOCS}, 0) /* 게시판네이버건수 */ , #{CRISIS_DSCSN_RLS_CN} /* 위기상담공개내용 */ , #{CRISIS_DSCSN_SECRE_CN} /* 위기상담비밀내용 */ , #{DAUM_CRCO_CN} /* DAUM위기상담내용 */ , #{NAVER_CRISIS_DSCSN_CN} /* 네이버위기상담내용 */ , NVL(#{CHTT_NOCS}, 0) /* 채팅건수 */ , #{CHTT_CRISIS_DSCSN_CN} /* 채팅위기상담내용 */ , NVL(#{CRCO_CAFE_NOCS}, 0) /* 위기상담카페건수 */ , #{ETC_DTL_CN} /* 기타상세내용 */ , #{TASKWK_SCHDL_SN} /* 업무일정일련번호 */ , REPLACE(#{WORK_YMD}, '-', '') /* 근무일자 */ , TO_DATE(#{WORK_BGNG_DT}, 'YYYY-MM-DD HH24:MI:SS') /* 근무시작일시 */ , TO_DATE(#{WORK_END_DT}, 'YYYY-MM-DD HH24:MI:SS') /* 근무종료일시 */ , TO_DATE(#{NTABRD_JOB_BGNG_DT}, 'YYYY-MM-DD HH24:MI:SS') /* 게시판작업시작일시 */ , TO_DATE(#{NTABRD_JOB_END_DT}, 'YYYY-MM-DD HH24:MI:SS') /* 게시판작업종료일시 */ , #{RVSN_CHTT_DSCSN_EVL_SCORE1} /* 개정채팅상담평가점수1 (SEQ) */ , #{RVSN_CHTT_DSCSN_EVL_SCORE2} /* 개정채팅상담평가점수2 (SEQ) */ , #{RVSN_CHTT_DSCSN_EVL_SCORE3} /* 개정채팅상담평가점수3 (SEQ) */ , #{RVSN_CHTT_DSCSN_EVL_SCORE4} /* 개정채팅상담평가점수4 (SEQ) */ , #{RVSN_CHTT_DSCSN_EVL_SCORE5} /* 개정채팅상담평가점수5 (SEQ) */ , #{RVSN_CHTT_DSCSN_EVL_SCORE6} /* 개정채팅상담평가점수6 (SEQ) */ , #{RVSN_CHTT_DSCSN_EVL_SCORE7} /* 개정채팅상담평가점수7 (SEQ) */ , #{RVSN_CHTT_DSCSN_EVL_SCORE8} /* 개정채팅상담평가점수8 (SEQ) */ , #{CHTT_OVERAL_RELEVA_SCORE} /* 채팅전반적적절성점수 */ , #{CHTT_DSCSN_EVL_THTS_PLAN_CN} /* 채팅상담평가소감계획내용 */ , #{CHRO_NO} /* 채팅방번호 */ , '2' /* 개정전후구분코드 */ , #{BBSCTT_TYPE_SE_CD} /* 게시글유형구분코드 */ , #{BBSCTT_ESNTAL_NO} /* 게시글고유번호 */ , #{RETE_ESNTAL_NO} /* 답글고유번호 */ , #{RVSN_NTABRD_DSCSN_EVL_SCORE1} /* 개정게시판상담평가점수1 (SEQ) */ , #{RVSN_NTABRD_DSCSN_EVL_SCORE2} /* 개정게시판상담평가점수2 (SEQ) */ , #{RVSN_NTABRD_DSCSN_EVL_SCORE3} /* 개정게시판상담평가점수3 (SEQ) */ , #{RVSN_NTABRD_DSCSN_EVL_SCORE4} /* 개정게시판상담평가점수4 (SEQ) */ , #{RVSN_NTABRD_DSCSN_EVL_SCORE5} /* 개정게시판상담평가점수5 (SEQ) */ , #{RVSN_NTABRD_DSCSN_EVL_SCORE6} /* 개정게시판상담평가점수6 (SEQ) */ , #{RVSN_NTABRD_DSCSN_EVL_SCORE7} /* 개정게시판상담평가점수7 (SEQ) */ , #{NTABRD_OVERAL_RELEVA_SCORE} /* 게시판전반적적절성점수 */ , #{NTABRD_DSCSN_EVL_THTS_PLAN_CN} /* 게시판상담평가소감계획내용 */ , NVL(#{NTABRD_NOCS}, 0) /* 게시판건수 (댓글상담실 + 이음-e) */ , NVL(#{CMNT_SLRBT_PRFMNC_NOCS}, 0) /* 댓글솔로봇실적건수 */ , NVL(#{NTABRD_SLRBT_PRFMNC_NOCS}, 0) /* 게시판솔로봇실적건수 */ , NVL(#{JAM_PSTG_NOCS}, 0) /* JAM게시건수 */ , #{JAM_CRISIS_CN} /* JAM위기내용 */ , NVL(#{MSNGR_NOCS}, 0) /* 메신저건수(아웃리치) */ , #{MSNGR_CRCO_CN} /* 메신저위기상담내용 (아웃리치) */ , NVL(#{CMNT_DSCSN_NOCS}, 0) /* 댓글상담건수 (아웃리치) */ , #{CMNT_DSCSN_CRCO_CN} /* 댓글상담위기상담내용 (아웃리치) */ , NVL(#{PR_NOCS}, 0) /* 홍보건수 */ , #{PR_CRCO_CN} /* 홍보위기상담내용 (아웃리치) */ , 0 /* 아웃리치챌린지실적건수 : AS-IS 사용안함? */ , #{RGTR_ID} /* 최초등록자아이디 */ , SYSDATE /* 최초등록일시 */ , #{RGTR_ID} /* 최종수정자아이디 */ , SYSDATE /* 최종수정일시 */ )

